// SmartHelmet/Software/src/components/SurveillanceTunnelMap.jsx

import { useMemo } from 'react';
import { TUNNEL_GRAPH, THRESHOLDS } from '../utils/constants';
import { runDijkstra } from '../services/api';
import '../styles/SurveillanceTunnelMap.css';

/* ==========================================================================
   SURVEILLANCE TUNNEL MAP
   ========================================================================== */

const VB_W = 1200;
const VB_H = 600;

// Artistic coordinate mapping that preserves logical topology
const NODES = {
  'Entrance':       { x: 120,  y: 300 },
  'Main Junction':  { x: 350,  y: 300 },
  'West Junction':  { x: 550,  y: 160 },
  'East Junction':  { x: 550,  y: 440 },
  'Zone A':         { x: 850,  y: 100 },
  'Zone B':         { x: 1000, y: 300 },
  'Zone C':         { x: 850,  y: 500 },
};

// Main logical routes using smooth cubic bezier curves
const EDGES = [
  { from: 'Entrance',      to: 'Main Junction',  d: 'M 120 300 C 200 300, 250 300, 350 300' },
  { from: 'Main Junction', to: 'West Junction',   d: 'M 350 300 C 450 300, 450 160, 550 160' },
  { from: 'Main Junction', to: 'East Junction',   d: 'M 350 300 C 450 300, 450 440, 550 440' },
  { from: 'West Junction', to: 'Zone A',          d: 'M 550 160 C 650 160, 750 100, 850 100' },
  { from: 'West Junction', to: 'Zone B',          d: 'M 550 160 C 700 160, 850 300, 1000 300' },
  { from: 'East Junction', to: 'Zone B',          d: 'M 550 440 C 700 440, 850 300, 1000 300' },
  { from: 'East Junction', to: 'Zone C',          d: 'M 550 440 C 650 440, 750 500, 850 500' },
].map(e => ({ ...e, key: [e.from, e.to].sort().join('|') }));

// Secondary ambient galleries for visual depth (not used in routing)
const AMBIENT_GALLERIES = [
  'M 350 300 C 350 100, 600 60, 850 100', // Northern ambient loop
  'M 350 300 C 350 500, 600 540, 850 500', // Southern ambient loop
  'M 850 100 C 1050 100, 1150 200, 1000 300', // Far east loop
  'M 850 500 C 1050 500, 1150 400, 1000 300', // Far east loop bottom
];

const ZONE_LABELS = [
  { text: 'ZONE A', x: 750, y: 110 },
  { text: 'ZONE B', x: 1050, y: 310 },
  { text: 'ZONE C', x: 750, y: 490 },
  { text: 'WEST WING', x: 550, y: 100 },
  { text: 'EAST WING', x: 550, y: 500 },
];

function getHazardInfo(reading, status) {
  if (status !== 'warning' && status !== 'emergency') return null;

  let label = 'HAZARD ZONE';
  if (reading?.gas_level >= THRESHOLDS.gas_level.warning) {
    label = 'GAS HAZARD';
  } else if (reading?.temperature >= THRESHOLDS.temperature.warning) {
    label = 'HEAT HAZARD';
  } else if (reading?.force >= THRESHOLDS.force.warning) {
    label = 'IMPACT ALERT';
  } else if (reading?.heart_rate > 0 && 
    (reading.heart_rate <= THRESHOLDS.heart_rate.warningLow || reading.heart_rate >= THRESHOLDS.heart_rate.warningHigh)) {
    label = 'VITAL ALERT';
  }

  return {
    label,
    isEmergency: status === 'emergency',
  };
}

export default function SurveillanceTunnelMap({ worker, reading, zone, status }) {
  const activeZone = zone || 'Entrance';
  const workerPos = NODES[activeZone] || NODES['Entrance'];
  const rssi = reading?.rssi ?? null;
  const workerName = worker?.name || worker?.worker_id || 'Worker';

  const isDanger = status === 'warning' || status === 'emergency';
  const isEmergency = status === 'emergency';
  const hazardInfo = getHazardInfo(reading, status);

  // Compute rescue route
  const rescueRouteNodes = useMemo(() => {
    if (!isDanger) return [];
    const target = NODES[activeZone] ? activeZone : 'Zone B';
    const path = runDijkstra(TUNNEL_GRAPH, 'Entrance', target);
    return path.length > 0 ? path : ['Entrance', 'Main Junction', 'West Junction', 'Zone B'];
  }, [isDanger, activeZone]);

  const rescueEdgeKeys = useMemo(() => {
    const keys = new Set();
    for (let i = 0; i < rescueRouteNodes.length - 1; i++) {
      keys.add([rescueRouteNodes[i], rescueRouteNodes[i + 1]].sort().join('|'));
    }
    return keys;
  }, [rescueRouteNodes]);

  return (
    <div className="surveillance-map-card">
      {/* ── Background Layers ── */}
      <div className="stm-background-layers">
        <div className="stm-grid-overlay" />
        <div className="stm-haze" />
        <div className="stm-vignette" />
      </div>

      {/* ── Header Overlay ── */}
      <div className="surveillance-map-header">
        <div className="stm-header-left">
          <span className="surveillance-map-title">Tunnel Surveillance Map</span>
          <span className="surveillance-map-subtitle">Live position and rescue route guidance</span>
        </div>

        <div className={`stm-status-badge ${status || 'normal'}`}>
          <span className={`stm-status-dot ${status || 'normal'}`} />
          {isEmergency ? 'EMERGENCY' : isDanger ? 'WARNING' : 'ALL CLEAR'}
        </div>
      </div>

      {/* ── SVG Canvas ── */}
      <div className="surveillance-map-canvas">
        {!reading && !zone && (
          <div className="stm-awaiting-overlay">
            <div className="stm-awaiting-icon">📡</div>
            <div className="stm-awaiting-text">Awaiting location data</div>
          </div>
        )}

        <svg viewBox={`0 0 ${VB_W} ${VB_H}`} preserveAspectRatio="xMidYMid meet">
          <defs>
            <filter id="glow-heavy" x="-30%" y="-30%" width="160%" height="160%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="12" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            <filter id="glow-light" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="4" result="blur" />
              <feMerge>
                <feMergeNode in="blur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>

            <radialGradient id="hazard-fill" cx="50%" cy="50%" r="50%">
              <stop offset="0%" stopColor={isEmergency ? 'rgba(239, 68, 68, 0.25)' : 'rgba(249, 115, 22, 0.2)'} />
              <stop offset="60%" stopColor={isEmergency ? 'rgba(239, 68, 68, 0.1)' : 'rgba(249, 115, 22, 0.08)'} />
              <stop offset="100%" stopColor="transparent" />
            </radialGradient>
          </defs>

          {/* ── Faint Region Labels ── */}
          {ZONE_LABELS.map((lbl, idx) => (
            <text
              key={idx}
              x={lbl.x}
              y={lbl.y}
              fill="rgba(0, 180, 255, 0.04)"
              fontSize="64"
              fontWeight="900"
              fontFamily="'Plus Jakarta Sans', sans-serif"
              letterSpacing="0.2em"
              textAnchor="middle"
              dominantBaseline="middle"
              style={{ pointerEvents: 'none' }}
            >
              {lbl.text}
            </text>
          ))}

          {/* ── Ambient Secondary Tunnels ── */}
          <g strokeLinecap="round" opacity="0.4">
            {AMBIENT_GALLERIES.map((d, idx) => (
              <g key={`ambient-${idx}`}>
                <path d={d} fill="none" stroke="rgba(0, 140, 255, 0.15)" strokeWidth="8" />
                <path d={d} fill="none" stroke="rgba(0, 212, 255, 0.3)" strokeWidth="1.5" />
              </g>
            ))}
          </g>

          {/* ── Main Tunnel Network ── */}
          <g strokeLinecap="round">
            {/* Outer Fat Glow */}
            <g filter="url(#glow-heavy)" opacity="0.6">
              {EDGES.map(e => (
                <path key={`outer-${e.key}`} d={e.d} fill="none" stroke="rgba(0, 180, 255, 0.2)" strokeWidth="24" />
              ))}
            </g>
            {/* Cyan Body */}
            {EDGES.map(e => (
              <path key={`body-${e.key}`} d={e.d} fill="none" stroke="rgba(0, 212, 255, 0.3)" strokeWidth="10" />
            ))}
            {/* Bright Inner Core */}
            {EDGES.map(e => (
              <path key={`core-${e.key}`} d={e.d} fill="none" stroke="#00d4ff" strokeWidth="2" opacity="0.8" />
            ))}
          </g>

          {/* ── Active Rescue Path (Danger Only) ── */}
          {isDanger && (
            <g strokeLinecap="round">
              <g filter="url(#glow-heavy)">
                {EDGES.filter(e => rescueEdgeKeys.has(e.key)).map(e => (
                  <path key={`rescue-glow-${e.key}`} d={e.d} fill="none" 
                        stroke={isEmergency ? 'rgba(34, 197, 94, 0.6)' : 'rgba(34, 197, 94, 0.4)'} 
                        strokeWidth="28" />
                ))}
              </g>
              {EDGES.filter(e => rescueEdgeKeys.has(e.key)).map(e => (
                <path key={`rescue-body-${e.key}`} d={e.d} fill="none" stroke="#22c55e" strokeWidth="12" />
              ))}
              {EDGES.filter(e => rescueEdgeKeys.has(e.key)).map(e => (
                <path key={`rescue-core-${e.key}`} d={e.d} fill="none" stroke="#ffffff" strokeWidth="3" />
              ))}
              {EDGES.filter(e => rescueEdgeKeys.has(e.key)).map(e => (
                <path key={`rescue-dash-${e.key}`} d={e.d} fill="none" stroke="rgba(255, 255, 255, 0.7)" 
                      strokeWidth="3" strokeDasharray="12 24" className="stm-rescue-dash-flow" />
              ))}
            </g>
          )}

          {/* ── Hazard Region Overlay (Danger Only) ── */}
          {isDanger && hazardInfo && (
            <g transform={`translate(${workerPos.x}, ${workerPos.y})`} className="stm-hazard-contour">
              {/* Organic glowing blob centered on worker */}
              <path
                d="M 0 -110 C 80 -110, 140 -60, 140 0 C 140 80, 60 140, 0 140 C -80 140, -140 70, -140 -15 C -140 -80, -70 -110, 0 -110 Z"
                fill="url(#hazard-fill)"
                stroke={isEmergency ? '#ef4444' : '#f97316'}
                strokeWidth="2"
                strokeDasharray="10 8"
                filter="url(#glow-light)"
              />

              {/* Hazard Icon and Text */}
              <g transform="translate(100, -80)">
                <path d="M 0,-15 L 12,5 L -12,5 Z" fill="none" stroke={isEmergency ? '#ef4444' : '#f97316'} strokeWidth="1.5" />
                <circle cx="0" cy="0" r="1.5" fill={isEmergency ? '#ef4444' : '#f97316'} />
                <line x1="0" y1="-8" x2="0" y2="-3" stroke={isEmergency ? '#ef4444' : '#f97316'} strokeWidth="2" />
                <text x="0" y="20" fill={isEmergency ? '#ef4444' : '#f97316'} fontSize="11" fontWeight="800" textAnchor="middle" letterSpacing="0.05em">
                  {hazardInfo.label}
                </text>
              </g>
            </g>
          )}

          {/* ── Junction / Node Markers ── */}
          {Object.entries(NODES).map(([nodeName, pos]) => {
            const isRescue = rescueRouteNodes.includes(nodeName);
            const isWorker = nodeName === activeZone;
            if (nodeName === 'Entrance' || isWorker) return null; // handled separately

            return (
              <g key={nodeName} transform={`translate(${pos.x}, ${pos.y})`}>
                <circle r="8" fill="#030818" stroke={isRescue && isDanger ? '#22c55e' : 'rgba(0, 212, 255, 0.4)'} strokeWidth="2" />
                <circle r="3" fill={isRescue && isDanger ? '#22c55e' : '#00d4ff'} filter="url(#glow-light)" />
              </g>
            );
          })}

          {/* ── Entrance Marker ── */}
          <g transform={`translate(${NODES.Entrance.x}, ${NODES.Entrance.y})`}>
            {/* Dark background pill */}
            <rect x="-55" y="-14" width="80" height="28" rx="14" fill="#040a1a" stroke="rgba(0, 212, 255, 0.3)" strokeWidth="1.5" />
            <circle cx="-41" cy="0" r="8" fill="rgba(0, 212, 255, 0.15)" stroke="#00d4ff" strokeWidth="1.5" />
            <text x="-24" y="4" fill="#00d4ff" fontSize="10" fontWeight="800" letterSpacing="0.1em">ENTRANCE</text>
          </g>

          {/* ── Live Worker Marker ── */}
          {workerPos && (
            <g transform={`translate(${workerPos.x}, ${workerPos.y})`}>
              <circle className="stm-worker-pulse-ring" r="16" fill="rgba(0, 212, 255, 0.1)" stroke="#00d4ff" strokeWidth="2" />

              {/* Outer bright ring */}
              <circle r="18" fill="none" stroke="rgba(0, 212, 255, 0.5)" strokeWidth="1.5" filter="url(#glow-light)" />
              {/* Inner dark circle with bright border */}
              <circle r="12" fill="#020614" stroke="#00d4ff" strokeWidth="2.5" />

              {/* Worker Icon */}
              <circle cx="0" cy="-3" r="3" fill="#00d4ff" />
              <path d="M -5,6 C -5,2 -3,1 0,1 C 3,1 5,2 5,6 Z" fill="#00d4ff" />

              {/* Worker Label Badge */}
              <g transform="translate(0, 28)">
                <rect x="-40" y="-12" width="80" height="24" rx="4" fill="#040a1a" stroke="rgba(0, 212, 255, 0.4)" strokeWidth="1" />
                <text x="0" y="4" fill="#fff" fontSize="11" fontWeight="700" textAnchor="middle" fontFamily="'JetBrains Mono', monospace">
                  {workerName}
                </text>
              </g>
            </g>
          )}

          {/* ── North Compass ── */}
          <g transform="translate(60, 60)">
            <circle r="22" fill="none" stroke="rgba(0, 180, 255, 0.2)" strokeWidth="1.5" />
            <path d="M 0,-16 L 6,-3 L 0,-6 L -6,-3 Z" fill="#00d4ff" filter="url(#glow-light)" />
            <path d="M 0,16 L 6,3 L 0,6 L -6,3 Z" fill="rgba(160, 174, 192, 0.3)" />
            <text x="0" y="-22" fill="#00d4ff" fontSize="12" fontWeight="800" textAnchor="middle">N</text>
          </g>

          {/* ── Scale Line ── */}
          <g transform={`translate(60, ${VB_H - 120})`}>
            <line x1="0" y1="0" x2="150" y2="0" stroke="rgba(160, 174, 192, 0.5)" strokeWidth="1.5" />
            <line x1="0" y1="-5" x2="0" y2="5" stroke="rgba(160, 174, 192, 0.5)" strokeWidth="1.5" />
            <line x1="50" y1="-3" x2="50" y2="3" stroke="rgba(160, 174, 192, 0.4)" strokeWidth="1" />
            <line x1="100" y1="-3" x2="100" y2="3" stroke="rgba(160, 174, 192, 0.4)" strokeWidth="1" />
            <line x1="150" y1="-5" x2="150" y2="5" stroke="rgba(160, 174, 192, 0.5)" strokeWidth="1.5" />

            <text x="0" y="20" fill="rgba(160, 174, 192, 0.7)" fontSize="10" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">0</text>
            <text x="50" y="20" fill="rgba(160, 174, 192, 0.7)" fontSize="10" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">50</text>
            <text x="100" y="20" fill="rgba(160, 174, 192, 0.7)" fontSize="10" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">100</text>
            <text x="150" y="20" fill="rgba(160, 174, 192, 0.7)" fontSize="10" fontFamily="'JetBrains Mono', monospace" textAnchor="middle">150m</text>
          </g>

        </svg>
      </div>

      {/* ── Footer Overlay ── */}
      <div className="surveillance-map-footer">
        <div className="surveillance-map-legend">
          <div className="stm-legend-item">
            <div className="stm-legend-swatch tunnel" /> Tunnel Network
          </div>
          <div className="stm-legend-item">
            <div className="stm-legend-swatch worker" /> Worker Position
          </div>
          <div className="stm-legend-item">
            <div className="stm-legend-swatch rescue" /> Rescue Path
          </div>
          <div className="stm-legend-item">
            <div className="stm-legend-swatch hazard" /> Hazard Zone
          </div>
        </div>

        <div className="surveillance-map-summary">
          <div className="stm-summary-block">
            <span className="stm-summary-label">Current Zone</span>
            <span className="stm-summary-value zone">{activeZone}</span>
          </div>
          <div className="stm-summary-block">
            <span className="stm-summary-label">Signal RSSI</span>
            <span className="stm-summary-value rssi">{rssi != null ? `${rssi} dBm` : '—'}</span>
          </div>
        </div>
      </div>
    </div>
  );
}
